import { useState } from 'react';

type Props = { options: { label: string; value: string }[] };

export default function {{component_name}}({ options }: Props) {
  const [value, setValue] = useState(options[0]?.value);
  return (
    <div>
      {options.map((o) => (
        <label key={o.value} className="block">
          <input
            type="radio"
            name="{{group_name}}"
            value={o.value}
            checked={value === o.value}
            onChange={(e) => setValue(e.target.value)}
          />
          <span className="ml-2">{o.label}</span>
        </label>
      ))}
    </div>
  );
}
